package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MathInternalError;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.MathInternalError;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for BaseSecantSolver.doSolve().
 * Since doSolve is protected, we use a Testable subclass to expose it.
 */
public class BaseSecantSolver_doSolve_TriageGen0Test {

    private enum Method {
        ILLINOIS, PEGASUS, REGULA_FALSI
    }

    private enum AllowedSolution {
        ANY_SIDE, LEFT_SIDE, RIGHT_SIDE, BELOW_SIDE, ABOVE_SIDE
    }

    /**
     * Testable subclass to expose protected methods and allow setting state.
     */
    private static class TestableSecantSolver extends BaseSecantSolver {
        private UnivariateRealFunction function;
        private double min;
        private double max;
        private double ftol = 1e-10;
        private double atol = 1e-10;
        private double rtol = 1e-10;
        private AllowedSolution allowed = AllowedSolution.ANY_SIDE;
        private Method method;

        public TestableSecantSolver(double rtol, double atol, double ftol, Method method, AllowedSolution allowed) {
            super(rtol, atol, ftol, method);
            this.rtol = rtol;
            this.atol = atol;
            this.ftol = ftol;
            this.method = method;
            this.allowed = allowed;
        }

        // Overriding to simulate the solver environment
        @Override
        protected double getMin() { return min; }
        @Override
        protected double getMax() { return max; }
        @Override
        protected double computeObjectiveValue(double x) { return function.value(x); }
        @Override
        protected void verifyBracketing(double x0, double x1) {
            if (function.value(x0) * function.value(x1) > 0) {
                throw new IllegalArgumentException("Not bracketed");
            }
        }
        @Override
        protected double getFunctionValueAccuracy() { return ftol; }
        @Override
        protected double getAbsoluteAccuracy() { return atol; }
        @Override
        protected double getRelativeAccuracy() { return rtol; }

        // Accessor for internal field 'method' if it were accessible, 
        // but here we pass it via constructor to simulate the logic in doSolve

        public void setFunction(UnivariateRealFunction f) { this.function = f; }
        public void setBounds(double min, double max) { this.min = min; this.max = max; }
        public void setAllowed(AllowedSolution allowed) { this.allowed = allowed; }
        public void setFtol(double ftol) { this.ftol = ftol; }
    }

    // Note: BaseSecantSolver is abstract, so we must use a concrete implementation 
    // or the Testable subclass. Since the prompt implies testing the logic within doSolve,
    // we assume the Testable subclass maps correctly to the logic provided.

    @Test
    public void testExactRootAtMin() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x); // root at 0
        solver.setBounds(0.0, 1.0);
        assertEquals(0.0, solver.doSolve(), 1e-15);
    }

    @Test
    public void testExactRootAtMax() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 1.0); // root at 1
        solver.setBounds(0.0, 1.0);
        assertEquals(1.0, solver.doSolve(), 1e-15);
    }

    @Test
    public void testExactRootInMiddle() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 0.5);
        solver.setBounds(0.0, 1.0);
        assertEquals(0.5, solver.doSolve(), 1e-10);
    }

    @Test
    public void testIllinoisMethod() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> Math.pow(x, 3) - x); // roots at -1, 0, 1. Bracketing [0.5, 1.5] -> root 1
        solver.setBounds(0.5, 1.5);
        assertEquals(1.0, solver.doSolve(), 1e-7);
    }

    @Test
    public void testPegasusMethod() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.PEGASUS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x * x - 2); // root sqrt(2)
        solver.setBounds(1.0, 2.0);
        assertEquals(Math.sqrt(2), solver.doSolve(), 1e-7);
    }

    @Test
    public void testRegulaFalsiMethod() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.REGULA_FALSI, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 0.5);
        solver.setBounds(0.0, 1.0);
        assertEquals(0.5, solver.doSolve(), 1e-7);
    }

    @Test
    public void testInvertedIntervalAndAllowedSides() {
        // We force an inversion by providing bounds where x0 > x1 if the logic allows, 
        // but the code uses x0 = getMin() and x1 = getMax(). 
        // However, the 'inverted' flag toggles when f1 * fx < 0.

        // Case: LEFT_SIDE with inversion
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.LEFT_SIDE);
        solver.setFunction(x -> x - 0.7);
        solver.setBounds(0.0, 1.0);
        // The logic for LEFT_SIDE returns inverted ? x1 : x0.
        // We test convergence and the allowed logic.
        double result = solver.doSolve();
        assertEquals(0.7, result, 1e-7);
    }

    @Test
    public void testFtolStopCondition() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.1, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.setFunction(x -> x - 0.5);
        solver.setBounds(0.0, 1.0);
        // Should stop when |f1| <= 0.1
        double result = solver.doSolve();
        assertEquals(0.5, result, 0.2);
    }

    @Test
    public void testAllowedSideLogic() {
        // Test BELOW_SIDE (f1 <= 0)
        TestableSecantSolver solverBelow = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.BELOW_SIDE);
        solverBelow.setFunction(x -> x - 0.5);
        solverBelow.setBounds(0.0, 1.0);
        assertEquals(0.5, solverBelow.doSolve(), 1e-7);

        // Test ABOVE_SIDE (f1 >= 0)
        TestableSecantSolver solverAbove = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ABOVE_SIDE);
        solverAbove.setFunction(x -> x - 0.5);
        solverAbove.setBounds(0.0, 1.0);
        assertEquals(0.5, solverAbove.doSolve(), 1e-7);
    }

    @Test
    public void testRegulaFalsiStagnation() {
        // Force x == x1 to trigger the Regula Falsi adjustment
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.REGULA_FALSI, AllowedSolution.ANY_SIDE);
        // A linear function where the secant method hits the root in one step
        solver.setFunction(x -> x - 0.5);
        solver.setBounds(0.0, 1.0);
        assertEquals(0.5, solver.doSolve(), 1e-7);
    }

    @Test
    public void testInternalErrorOnUnknownMethod() {
        // This requires a way to pass an invalid method. 
        // Since Method is an enum, we'd need to use reflection or a mock if it weren't final.
        // Given the provided code, we can't easily trigger 'default' without reflection.
        // But we can simulate the logic if we could.
    }
}
